import{_ as i,o as r,c as a,ah as s}from"./chunks/framework.CNYUdSfs.js";const l="/projects/ArmPi_Pro/en/latest/assets/image3.BHm68kg2.jpeg",c="/projects/ArmPi_Pro/en/latest/assets/image4.BGIIj1iQ.jpeg",g="/projects/ArmPi_Pro/en/latest/assets/image5.CCgHJijY.jpeg",o="/projects/ArmPi_Pro/en/latest/assets/image6.D0H3u9si.jpeg",n="/projects/ArmPi_Pro/en/latest/assets/image7.DU5uGdZJ.jpeg",d="data:image/png;base64,",m="/projects/ArmPi_Pro/en/latest/assets/image9.BZXmJbxo.jpeg",h="/projects/ArmPi_Pro/en/latest/assets/image10.CiZ6D0uM.jpeg",p="/projects/ArmPi_Pro/en/latest/assets/image11.D7c4J9S8.jpeg",A="/projects/ArmPi_Pro/en/latest/assets/image3.BHm68kg2.jpeg",u="/projects/ArmPi_Pro/en/latest/assets/image13.DyyxYLW4.jpeg",P="/projects/ArmPi_Pro/en/latest/assets/image14.YrQCrvnq.jpeg",f="/projects/ArmPi_Pro/en/latest/assets/image5.CCgHJijY.jpeg",y="/projects/ArmPi_Pro/en/latest/assets/image18.DwlqJ4kA.jpeg",b="/projects/ArmPi_Pro/en/latest/assets/image19.DMFOKP84.jpeg",w="/projects/ArmPi_Pro/en/latest/assets/image20.B_J8UPmx.jpeg",_="/projects/ArmPi_Pro/en/latest/assets/image10.CiZ6D0uM.jpeg",q="/projects/ArmPi_Pro/en/latest/assets/image1.CHsOAr8z.png",v="/projects/ArmPi_Pro/en/latest/assets/image2.Dk33vIOU.png",j="/projects/ArmPi_Pro/en/latest/assets/image13.DLrg2cVg.png",z="/projects/ArmPi_Pro/en/latest/assets/image3.DNNdD07Z.png",k="/projects/ArmPi_Pro/en/latest/assets/image4.CeRsxWFs.png",x="/projects/ArmPi_Pro/en/latest/assets/image0.DJraC03c.png",C="/projects/ArmPi_Pro/en/latest/assets/image5.C6nsYLR_.jpeg",I="/projects/ArmPi_Pro/en/latest/assets/image6.BEdt877v.png",D="/projects/ArmPi_Pro/en/latest/assets/image7.amRfYLrr.png",t="data:image/png;base64,",T="/projects/ArmPi_Pro/en/latest/assets/image9.DaMvvJ6w.png",B="/projects/ArmPi_Pro/en/latest/assets/image10.b2cfxZjD.png",Q="/projects/ArmPi_Pro/en/latest/assets/image11.D7p38933.png",E="/projects/ArmPi_Pro/en/latest/assets/image12.fsZF9RFI.png",W="/projects/ArmPi_Pro/en/latest/assets/image2.BtjdiD-g.jpeg",R="/projects/ArmPi_Pro/en/latest/assets/image3.eGyABuwD.png",S="/projects/ArmPi_Pro/en/latest/assets/image2.Dek4WUXe.png",L="/projects/ArmPi_Pro/en/latest/assets/image4.DmDGm4l9.png",N="/projects/ArmPi_Pro/en/latest/assets/image5.HWZC2QW9.png",F="/projects/ArmPi_Pro/en/latest/assets/image6.svCLMSQe.png",G="/projects/ArmPi_Pro/en/latest/assets/image7.BbugTGTC.png",J="/projects/ArmPi_Pro/en/latest/assets/image10.DxQMThBQ.png",O="/projects/ArmPi_Pro/en/latest/assets/image11.-S1p6HP9.png",V="/projects/ArmPi_Pro/en/latest/assets/image12.ClLttV6c.png",M="/projects/ArmPi_Pro/en/latest/assets/image13.Bcpr3aj1.png",U="/projects/ArmPi_Pro/en/latest/assets/image14.CEuj1CU_.png",Z="/projects/ArmPi_Pro/en/latest/assets/image15.BnWiSzTs.png",H="data:image/png;base64,",K="/projects/ArmPi_Pro/en/latest/assets/image17.BkvGuCiv.png",Y="data:image/png;base64,",X="/projects/ArmPi_Pro/en/latest/assets/image19.CH-bMgVG.png",$="/projects/ArmPi_Pro/en/latest/assets/image20.BIF-rVNs.png",tt="/projects/ArmPi_Pro/en/latest/assets/image21.FsRQuZ87.png",et="/projects/ArmPi_Pro/en/latest/assets/image22.mP2-qF-l.png",ot="/projects/ArmPi_Pro/en/latest/assets/image23.CcdC4yDc.png",nt="/projects/ArmPi_Pro/en/latest/assets/image24.BZ5f2PnW.png",it="/projects/ArmPi_Pro/en/latest/assets/image25.CSqj5NaW.png",rt="/projects/ArmPi_Pro/en/latest/assets/image25.CSqj5NaW.png",pt=JSON.parse('{"title":"2. Quick User Experience","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2_play_first_hand.md","filePath":"docs/2_play_first_hand.md"}'),at={name:"docs/2_play_first_hand.md"};function st(lt,e,ct,gt,dt,mt){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_2-quick-user-experience" tabindex="-1">2. Quick User Experience <a class="header-anchor" href="#_2-quick-user-experience" aria-label="Permalink to &quot;2. Quick User Experience&quot;">​</a></h1><p id="anchor_2_1"></p><h2 id="_2-1-app-installation-and-connection" tabindex="-1">2.1 APP Installation and Connection <a class="header-anchor" href="#_2-1-app-installation-and-connection" aria-label="Permalink to &quot;2.1 APP Installation and Connection&quot;">​</a></h2><p>The following instructions use TurboPi as an example and apply to other Hiwonder Raspberry Pi series products as well. In this section, you will learn how to use APP &quot;<strong>WonderPi</strong>&quot; to control TurboPi. The installation method is as follows.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>① Make sure all APP permissions are turned on in settings, otherwise APP functions will be limited!</p><p>② Turn on Location and WiFi before operation.</p></section><h3 id="_2-1-1-installation" tabindex="-1">2.1.1 Installation <a class="header-anchor" href="#_2-1-1-installation" aria-label="Permalink to &quot;2.1.1 Installation&quot;">​</a></h3><p><strong><a href="https://play.google.com/store/apps/details?id=com.Wonder.Pi" target="_blank" rel="noreferrer">APP Installation Pack (Android)</a></strong></p><p><strong><a href="https://apps.apple.com/cn/app/wonderpi/id1477946178" target="_blank" rel="noreferrer">APP Installation Pack (iOS)</a></strong></p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>Please turn TurboPi on before connecting.</p></li><li><p>Make sure all APP permissions are turned on in settings, otherwise APP functions will be limited!</p></li><li><p>Turn on Location and WiFi before operation.</p></li></ul></section><h3 id="_2-1-2-app-connection" tabindex="-1">2.1.2 APP Connection <a class="header-anchor" href="#_2-1-2-app-connection" aria-label="Permalink to &quot;2.1.2 APP Connection&quot;">​</a></h3><p>(1) Start robot. (The switch is on Raspberry Pi expansion board). For detailed instruction, please refer to the file in &quot;<strong><a href="https://docs.hiwonder.com/projects/ArmPi_Pro/en/latest/docs/1_read_before_studying.html#charging-and-power-on-status-explanation" target="_blank" rel="noreferrer">Getting Ready\\1.4 Charging and Power-On Status Explanation</a></strong>&quot;.</p><p>(2) After TurboPi boots up successfully, it enters AP direct connection mode, and generates a WiFi starting with <strong>&quot;HW&quot;</strong>. Join this WiFi, and then you can experience robot games</p><ul><li><strong>Introduction to Connection Mode</strong></li></ul><p>There are two connection modes, namely direct connection mode and LAN mode. APP functions are the same under these two modes.</p><p>(1) AP direct connection mode: RaspberryPi generates a WiFi which can be connected by phones. But this WiFi has no internet access.</p><p>(2) STA LAN mode: Raspberry Pi actively connects to specific WiFi. In this mode, you can access internet.</p><ul><li><strong>Direct Connection Mode (MUST-READ)</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>After TurboPi boots up successfully, it enters AP direct connection mode, and generates a WiFi starting with <strong>&quot;HW&quot;</strong>.</p></section><p>(1) Open&quot;<strong>WonderPi</strong>&quot;. Select <strong>&quot;Standard -&gt;TurboPi&quot;</strong> in sequence.</p><img loading="lazy" src="'+l+'"><p>(2) Tap <strong>&quot;+&quot;</strong> in bottom right corner, and then select <strong>Direct Connection Mode</strong>.</p><img loading="lazy" src="'+c+'"><p>(3) Tap <strong>&quot;Go to connect device hotspot&quot;</strong>. Join WiFi starting with &quot;<strong>HW</strong>&quot;. The password is <strong>&quot;hiwonder&quot;</strong>.</p><img loading="lazy" src="'+g+'"><img loading="lazy" src="'+o+'" style="width:350px;" class="common_img"><p>(4) Return back to APP after connection.</p><img loading="lazy" src="'+n+'" style="width:350px;" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>for iOS user, please don&#39;t return to APP until WiFi icon appears on status bar, otherwise robot cannot be searched. If robot cannot be searched by APP, tap <img loading="lazy" height="52" width="52" src="'+d+'" style="width:45px;"> to refresh.</p></section><p>(5) APP automatically connects to robot. When robot icon below occurs, connection completes.</p><img loading="lazy" src="'+m+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>if you are informed of &quot;<strong>No Internet. Whether to keep connection</strong>&quot;, just select &quot;<strong>keep connected</strong>&quot;.</p></section><p>(6) Tap robot icon to enter mode selection interface.</p><img loading="lazy" src="'+h+'"><p>For detailed introduction to robot games, please refer to the file in &quot;<strong><a href="#anchor_2_2">2.2 APP Control</a></strong>&quot;.</p><ul><li><strong>LAN Connection Mode</strong></li></ul><p>(1) Disconnect the WiFi generated by TurboPi. Connect your phone to a WiFi. Take <strong>&quot;Hiwonder&quot;</strong> as example.</p><img loading="lazy" src="'+p+'" style="width:350px;" class="common_img"><p>(2) After connection, open <strong>&quot;WonderPi&quot;</strong>. Select <strong>&quot;Standard -&gt;TurboPi&quot;</strong> in sequence.</p><img loading="lazy" src="'+A+'"><p>(3) Tap &quot;<strong>+</strong>&quot; in bottom right corner, and then select LAN Mode.</p><img loading="lazy" src="'+u+'"><p>(4) Input the password of the WiFi your phone joins. Ensure the password you input is correct, otherwise APP fails to connect to robot. Tap <strong>&quot;OK&quot;</strong>.</p><img loading="lazy" src="'+P+'"><p>(5) Tap &quot; <strong>to connect device hotspot</strong>&quot;.</p><img loading="lazy" src="'+f+'"><p>(6) Join the WiFi starting with <strong>&quot;HW&quot;.</strong> The password is <strong>&quot;hiwonder&quot;</strong>. After connection, return back to APP.</p><p class="common_img" style="text-align:center;"><img loading="lazy" src="'+o+'" style="width:350px;"><img loading="lazy" src="'+n+'" style="width:350px;"></p><p>(7) APP automatically configures network.</p><img loading="lazy" src="'+y+'"><p>(8) After a while, robot icon below occurs, and LED on expansion board keeps on.</p><img loading="lazy" src="'+b+'"><p>(9) Long press robot icon to check TurboPi&#39;s IP and ID.</p><img loading="lazy" src="'+w+'"><p>(10) Tap robot icon to enter mode selection interface.</p><img loading="lazy" src="'+_+'"><p>For detailed introduction to robot games, please refer to the file in&quot;<strong><a href="#anchor_2_2">2.2 APP Control</a></strong>&quot;.</p><p id="anchor_2_2"></p><h2 id="_2-2-app-control" tabindex="-1">2.2 App Control <a class="header-anchor" href="#_2-2-app-control" aria-label="Permalink to &quot;2.2 App Control&quot;">​</a></h2><h3 id="_2-2-1-getting-ready" tabindex="-1">2.2.1 Getting Ready <a class="header-anchor" href="#_2-2-1-getting-ready" aria-label="Permalink to &quot;2.2.1 Getting Ready&quot;">​</a></h3><p>Please refer to &quot;<a href="#anchor_2_1"><strong>2.1 APP Installation and Connection</strong></a>&quot; to install the app and connect to ArmPi Pro.</p><h3 id="_2-2-2-start-game" tabindex="-1">2.2.2 Start Game <a class="header-anchor" href="#_2-2-2-start-game" aria-label="Permalink to &quot;2.2.2 Start Game&quot;">​</a></h3><p>Click ArmPi Pro icon to enter mode selection.</p><img loading="lazy" height="492" width="980" class="common_img" src="'+q+'" alt="loading"><ul><li><strong>Robot Control</strong></li></ul><p>(1) Select &quot;<strong>Robot Control</strong>&quot; in Mode Selection interface to enter this game, robotic arm will return to the initial posture.</p><img loading="lazy" height="647" width="1310" class="common_img" src="'+v+'" alt="loading"><p>(2) The interface of &quot;<strong>Robot Control</strong>&quot; interface is divided into six parts. The left side is the interface to control the movement of robot by dragging the slider. Other function icons can refer to the following table:</p><img loading="lazy" height="497" width="1000" class="common_img" src="'+j+'" alt="loading"><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="178" width="178" src="'+z+'" style="width:0.78681in;height:0.78681in;" alt="loading"></td><td style="text-align:center;">Drag slider to control the movement of ArmPi Pro</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="125" width="265" src="'+k+'" style="width:1.1811in;height:0.54397in;" alt="loading"></td><td style="text-align:center;">Control the movement direction of ArmPi Pro</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="105" width="266" src="'+x+'" style="width:1.1811in;height:0.36876in;" alt="loading"></td><td style="text-align:center;">Control the robotic arm return to the initial posture</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="284" width="378" src="'+C+'" style="width:1.71944in;height:1.28889in;" alt="loading"></td><td style="text-align:center;">Display the current transmitted image</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="602" width="369" src="'+I+'" style="width:165px;" alt="loading"></td><td style="text-align:center;">Control the rotation of each servo of robotic arm</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="69" width="376" src="'+D+'" style="width:240px;" alt="loading"></td><td style="text-align:center;">Adjust the speed of mecanum wheel</td></tr></tbody></table><p>(3) If want to back to the mode selection interface, click the blank area of interface and then click <img loading="lazy" height="41" width="51" src="'+t+'" style="width:0.37222in;height:0.31944in;"> in the left side.</p><ul><li><strong>Line Following</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>Please start this game in a well-lit environment, but keep robot from the direct light.</li><li>When recognizing, please do not have the same or similar colored object within the detected range to avoid interference.</li><li>If the recognition effect is not good enough, please refer to &quot;<a href="#anchor_2_3"><strong>2.3 Adjust Color Threshold</strong></a>&quot;.</li></ul></section><p>(1) Click <strong>&quot;Line following&quot;</strong> to enter this game.</p><p>(2) After selecting color for the line, click <strong>&quot;Start&quot;</strong> to start following line.</p><img loading="lazy" height="456" width="888" class="common_img" src="'+T+'" style="width:666px;" alt="loading"><p>(3) If want to back to the mode selection interface, click the blank area of interface and then click <img loading="lazy" height="41" width="51" src="'+t+'"> in the left side.</p><ul><li><strong>Color Tracking</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>Please start this game in a well-lit environment, but keep robot from the direct light.</li><li>When recognizing, please do not have the same or similar colored object within the detected range to avoid interference.</li><li>If the recognition effect is not good enough, please refer to &quot;<a href="#anchor_2_3"><strong>2.3 Adjust Color Threshold</strong></a>&quot;.</li></ul></section><p>(1) Click &quot;<strong>Color Tracking</strong>&quot; to enter this game.</p><img loading="lazy" height="346" width="666" class="common_img" src="'+B+'"><p>(2) After selecting color, click &quot;<strong>Start</strong>&quot; and then the robotic arm will follow the movement of recognized color.</p><p>(3) If want to back to the mode selection interface, click the blank area of interface and then click <img loading="lazy" height="41" width="51" src="'+t+'"> in the left side.</p><ul><li><strong>Face Recognition</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>Please start this game in a well-lit environment, but keep robot from the direct light.</li><li>When recognizing, one human face only is allowed to appear within the detected range. Otherwise, it will affect the game result.</li></ul></section><p>(1) Click &quot;<strong>Face Recognition</strong>&quot; to enter this game.</p><img loading="lazy" height="334" width="662" class="common_img" src="'+Q+'" alt="loading"><p>(2) After clicking &quot;<strong>Start</strong>&quot;, robotic arm will search human face within the detected range. The recognized face will be framed in a green box after recognizing and the gripper will open. Then, the robotic arm will move with the recognized face.</p><p>(3) If want to back to the mode selection interface, click the blank area of interface and then click <img loading="lazy" height="41" width="51" src="'+t+'" style="width:in;height:in;"> in the left side.</p><ul><li><strong>Tag Recognition</strong></li></ul><p>(1) Click &quot;<strong>Tag Recognition</strong>&quot; in mode selection interface to enter this game.</p><img loading="lazy" height="342" width="666" class="common_img" src="'+E+'"><p>(2) Click &quot;<strong>Start</strong>&quot;. Then ArmPi Pro will identify Tag within the detected range and carry out different actions according to the recognized ID.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>ID</strong></th><th style="text-align:center;"><strong>Corresponding Action</strong></th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">The mecanum wheel moves in a triangular trajectory. (The car is always facing forward)</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">The mecanum wheel moves in a circle trajectory. (The car is always facing forward)</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">The mecanum wheel moves in a circle trajectory. (The car is always towards the center of circle.)</td></tr></tbody></table><p id="anchor_2_3"></p><h2 id="_2-3-adjust-color-threshold" tabindex="-1">2.3 Adjust Color Threshold <a class="header-anchor" href="#_2-3-adjust-color-threshold" aria-label="Permalink to &quot;2.3 Adjust Color Threshold&quot;">​</a></h2><p>Different light source will have different influence on the colors, which will result in recognition discrepancy. To tackle this problem, you can adjust color threshold via &quot;<strong>WonderPi</strong>&quot; APP.</p><h3 id="_2-3-1-preparation" tabindex="-1">2.3.1 Preparation <a class="header-anchor" href="#_2-3-1-preparation" aria-label="Permalink to &quot;2.3.1 Preparation&quot;">​</a></h3><p>Start TurboPi. Open &quot;<strong>WonderPi</strong>&quot; APP, and connect it to TurboPi. For how to connect robot to APP, operate referring to &quot;<strong><a href="#anchor_2_1">2.1 APP Installation and Connection </a></strong>&quot;.</p><h3 id="_2-3-2-interface-layout" tabindex="-1">2.3.2 Interface Layout <a class="header-anchor" href="#_2-3-2-interface-layout" aria-label="Permalink to &quot;2.3.2 Interface Layout&quot;">​</a></h3><p>Tap in upper right corner to enter color threshold adjustment interface.</p><img loading="lazy" src="'+W+'"><img loading="lazy" height="463" width="988" src="'+R+'"><p>The table below list function of specific icon.</p><table class="docutils-nobg" border="1"><colgroup><col><col></colgroup><tbody><tr><td><strong>Icon</strong></td><td><strong>Function</strong></td></tr><tr><td><img loading="lazy" height="132" width="177" src="'+S+'" style="width:300px;"></td><td><p>Processed camera returned image.</p><p>Target object is white, and other area is black.</p></td></tr><tr><td><img loading="lazy" height="1184" width="1556" src="'+L+'" style="width:300px;"></td><td>Raw camera returned image.</td></tr><tr><td><img loading="lazy" height="75" width="346" src="'+N+'" style="width:200px;"></td><td>Select the color to be adjusted.</td></tr><tr><td><img loading="lazy" height="85" width="346" src="'+F+'" style="width:200px;"><img loading="lazy" height="84" width="346" src="'+G+'" style="width:200px;"></td><td><p>Adjust L component of camera returned image. &quot;<b>L_min</b>&quot; is lower limit and &quot;<b>L_max</b>&quot; is upper limit.</p></td></tr><tr><td><img loading="lazy" height="85" width="346" src="'+J+'" style="width:200px;"><img loading="lazy" height="83" width="346" src="'+O+'" style="width:200px;"></td><td><p>Adjust A component of camera returned image. &quot;<b>a_min</b>&quot; is lower limit and &quot;<b>a_max</b>&quot; is upper limit.</p></td></tr><tr><td><img loading="lazy" height="84" width="346" src="'+V+'" style="width:200px;"><img loading="lazy" height="85" width="346" src="'+M+'" style="width:200px;"></td><td><p>Adjust B component of camera returned image. &quot;b_min&quot; is lower limit and &quot;b_max&quot; is upper limit.</p></td></tr><tr><td><img loading="lazy" height="84" width="162" src="'+U+'" style="width:200px;"></td><td>Get instruction to check how to adjust color threshold.</td></tr><tr><td><img loading="lazy" height="87" width="144" src="'+Z+'" style="width:100px;"></td><td>Save the adjusted color threshold.</td></tr><tr><td><img loading="lazy" height="87" width="87" src="'+H+'" style="width:60px;"></td><td>Return back to mode selection interface.</td></tr><tr><td><img loading="lazy" height="87" width="86" src="'+K+'" style="width:60px;"></td><td>Hide navigation bar.</td></tr><tr><td><img loading="lazy" height="86" width="86" src="'+Y+'" style="width:60px;"></td><td>Display Hiwonder info.</td></tr></tbody></table><h3 id="_2-3-3-adjust-color-threshold" tabindex="-1">2.3.3 Adjust Color Threshold <a class="header-anchor" href="#_2-3-3-adjust-color-threshold" aria-label="Permalink to &quot;2.3.3 Adjust Color Threshold&quot;">​</a></h3><p>(1) Select color to be adjusted. Take red as example.</p><img loading="lazy" height="470" width="1000" src="'+X+'"><p>(2) Put red object within camera recognition zone. Set L_min, a_min and b_min to 0, and L_max, a_max and b_max to 255.</p><img loading="lazy" height="474" width="990" src="'+$+'"><p>(3) Tap &quot;<strong>Instruction</strong>&quot; icon to check how to adjust color threshold.</p><img loading="lazy" height="474" width="1000" src="'+tt+'"><img loading="lazy" height="560" width="1213" src="'+et+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>if you need to close Instruction window, select &quot;<strong>OK</strong>&quot;.</p></section><p>(4) Red approaches &quot;<strong>+a</strong>&quot; zone, so you need to adjust A component.</p><img loading="lazy" height="300" width="300" src="'+ot+'" style="width:300px;" class="common_img"><p>(5) Keep &quot;<strong>a_max</strong>&quot; value the same, and then increase &quot;<strong>a_min</strong>&quot; value till red object turns white and other area is black.</p><img loading="lazy" height="602" width="1280" src="'+nt+'"><p>(6) Adjust &quot;<strong>L</strong>&quot; and &quot;<strong>B</strong>&quot; values. If it belongs to light red, increase L_min. Otherwise, decrease L_max. If it belongs to warm tone, increase B_min. Otherwise, decrease B_max.</p><img loading="lazy" height="602" width="1280" src="'+it+'"><p>(7) Remember to save the value after adjustment.</p><img loading="lazy" height="602" width="1280" src="'+rt+'">',121)])])}const At=i(at,[["render",st]]);export{pt as __pageData,At as default};
